    {type: "tablefill", source: "outline", id: "doc-bang-hanviet", title: "Bảng tổng hợp từ Hán Việt (tự điền nghĩa rồi đối chiếu)", columns: ["Từ Hán Việt", "Nghĩa", "Ví dụ trong bài"], rows: [["tiên triều", null, null], ["hàn sĩ", null, null], ["khoan dung", null, null], ["hiếu sinh", null, null], ["nghĩa khí", null, null], ["hoài bão tung hoành", null, null]], suggested: [["tiên triều", "triều đại, triều vua trước", "Chữ người tử tù"], ["hàn sĩ", "người học trò nghèo", "Chữ người tử tù"], ["khoan dung", "rộng lượng, tha thứ", "Chữ người tử tù"], ["hiếu sinh", "yêu quý sự sống", "Chữ người tử tù"], ["nghĩa khí", "tinh thần trọng lẽ phải", "Chữ người tử tù"], ["hoài bão tung hoành", "ước mơ, khát vọng lớn", "Chữ người tử tù"]]},
    {type: "h3", source: "outline", text: "Bài 2. Đoạn văn Huấn Cao nói với quản ngục"},
    {type: "p", source: "outline", text: "Đoạn văn: \"Ta nhất sinh không vì vàng ngọc hay quyền thế...\""},
    {type: "qa", source: "outline", id: "doc-hv-b2a", q: "a. Tìm 5 từ Hán Việt trong đoạn văn.", a: "Gợi ý: nhất sinh, quyền thế, tứ bình, trung đường, biệt nhỡn, liên tài, thiên hạ."},
    {type: "qa", source: "outline", id: "doc-hv-b2b", q: "b. Thay một từ Hán Việt bằng từ thuần Việt hoặc cụm từ tương đương, rồi so sánh.", a: "Ví dụ: nhất sinh thành suốt đời. Nghĩa vẫn đủ nhưng mất đi sắc thái trang trọng, cổ kính."},
    {type: "qa", source: "outline", id: "doc-hv-b2c", q: "c. Nêu tác dụng của từ Hán Việt trong đoạn văn.", a: "Tạo sắc thái trang trọng, cổ xưa, hợp bối cảnh thời phong kiến và phong thái của nhà nho như Huấn Cao. Từ Hán Việt cũng bộc lộ sự trân trọng và làm lời nói thêm cô đọng."},
    {type: "h3", source: "outline", text: "Bài 3. Tìm 6 từ Hán Việt rồi đặt câu"},
    {type: "p", source: "outline", text: "Yêu cầu của sách: tìm 6 từ Hán Việt có chứa một trong các yếu tố của cương trực, hàn sĩ, hiếu sinh, rồi đặt câu. Mục hàn đã được sửa lại cho đúng (xem ghi chú)."},
    {type: "tablefill", source: "outline", id: "doc-bang-bai3", title: "Từ gợi ý và đặt câu", columns: ["Yếu tố", "Từ gợi ý", "Đặt câu của em"], rows: [["cương", "cương quyết, kiên cường", null], ["trực", "chính trực, trực tiếp", null], ["sĩ", "chiến sĩ, dũng sĩ", null], ["hiếu", "hiếu học, hiếu chiến", null], ["sinh", "sinh viên, sinh tồn", null], ["hàn", "hàn lâm, hàn vi", null]], suggested: null},
    {type: "qa", source: "draft", id: "doc-hv-b3-vd", q: "Xem ví dụ đặt câu với các từ trên.", a: "Ví dụ tham khảo: Bạn Lan học hành rất cương quyết. Ông ấy là người chính trực. Các chiến sĩ canh giữ biên cương. Em trai tôi rất hiếu học. Sinh viên năm nhất đi tình nguyện. Viện hàn lâm công bố công trình mới. Anh ấy xuất thân hàn vi nhưng học rất giỏi."},
    {type: "h3", source: "outline", text: "Bài 4. Chỉ ra lỗi dùng từ Hán Việt và sửa"},
    {type: "qa", source: "outline", id: "doc-hv-b4a", q: "a. Lỗi trong cụm trí thức bổ ích là gì? Sửa thế nào?", a: "\"trí thức bổ ích\" sai, vì trí thức là người có học vấn. Sửa thành tri thức (kiến thức, hiểu biết)."},
    {type: "qa", source: "outline", id: "doc-hv-b4b", q: "b. Cụm cứng cỏi, ngang tàng của hàn sĩ có vấn đề gì?", a: "Có thể bị lệch sắc thái, vì ngang tàng hàm ý bướng bỉnh, bất chấp. Có thể sửa thành khí khái hoặc cương trực."},
    {type: "qa", source: "outline", id: "doc-hv-b4c", q: "c. Từ yếu điểm dùng đúng nghĩa là gì?", a: "\"yếu điểm\" là điểm quan trọng. Dùng đúng nghĩa điểm yếu là nhược điểm (điểm yếu)."},
    {type: "quiz", source: "outline", id: "doc-quiz-hanviet", title: "Tự kiểm tra: từ Hán Việt", questions: [
      {q: "Từ hàn sĩ có nghĩa là gì?", options: ["Người học trò nghèo", "Người lính già", "Người thợ rèn", "Người lái buôn"], answer: 0, explain: "hàn sĩ: người học trò nghèo."},
      {q: "Sửa lỗi: trí thức bổ ích dùng sai ở đâu?", options: ["trí thức phải sửa thành tri thức", "bổ ích phải sửa thành bổ trợ", "Không sai", "Bỏ cả hai từ"], answer: 0, explain: "trí thức là người có học vấn; kiến thức, hiểu biết là tri thức."},
      {q: "yếu điểm có nghĩa đúng là gì?", options: ["Điểm quan trọng", "Điểm yếu", "Điểm thấp", "Điểm trung bình"], answer: 0, explain: "\"yếu điểm\" là điểm quan trọng; điểm yếu là nhược điểm."},
      {q: "Thay nhất sinh bằng suốt đời thì mất đi điều gì?", options: ["Sắc thái trang trọng, cổ kính", "Nghĩa của câu", "Chủ ngữ", "Dấu câu"], answer: 0, explain: "Nghĩa vẫn đủ nhưng mất đi sắc thái trang trọng, cổ kính."}
    ]}
